# embed.sh — turns lang/*.txt and help/*.txt into C source on stdout.
#
# Usage: embed.sh FILE...
#
# lang/XX.txt holds "key = text" lines ("#" starts a comment, "\n" in the
# text is a newline); help/XX.txt is embedded as it is, except for "#"
# comment lines and the blank lines before the text. XX is the language
# code. Every language needs both files.
#
# Non-ASCII bytes are written as octal escapes, so the generated file is
# plain ASCII and does not depend on the compiler's source character set.
# Help texts are arrays of character constants: a string literal may be
# at most 4095 bytes long in C99 and C11, and -pedantic says so.

LC_ALL=C
export LC_ALL

LANGS=
for FILE in "$@"
do
	CODE=${FILE##*/}
	CODE=${CODE%.txt}
	case " $LANGS " in
	*" $CODE "*)
		;;
	*)
		LANGS="$LANGS $CODE"
		;;
	esac
done

for CODE in $LANGS
do
	FOUND_LANG=
	FOUND_HELP=
	for FILE in "$@"
	do
		case $FILE in
		*lang/"$CODE".txt)
			FOUND_LANG=$FILE
			;;
		*help/"$CODE".txt)
			FOUND_HELP=$FILE
			;;
		esac
	done
	if [ -z "$FOUND_LANG" ] || [ -z "$FOUND_HELP" ]
	then
		echo "embed.sh: language $CODE needs lang/$CODE.txt and help/$CODE.txt" >&2
		exit 1
	fi
done

echo '/* Generated by tools/embed.sh; do not edit. */'
echo
echo '#include <stddef.h>'
echo
echo '#include "msg.h"'

for FILE in "$@"
do
	CODE=${FILE##*/}
	CODE=${CODE%.txt}
	case $FILE in
	*lang/*)
		KIND=lang
		;;
	*)
		KIND=help
		;;
	esac
	awk -v KIND="$KIND" -v CODE="$CODE" -v FILE="$FILE" '
	BEGIN {
		for (i = 1; i < 256; i++)
			ORD[sprintf("%c", i)] = i
		if (KIND == "lang")
			printf "\nstatic const struct catalog_entry entries_%s[] = {\n", CODE
		else
			printf "\nstatic const char help_%s[] = {\n", CODE
	}
	# Escapes a string for a C literal; "\n" stays a newline escape when
	# keep_newline is set and is a literal backslash and n otherwise.
	function cstr(s, keep_newline,    out, i, c, o) {
		out = ""
		for (i = 1; i <= length(s); i++) {
			c = substr(s, i, 1)
			o = ORD[c]
			if (c == "\\" && keep_newline && substr(s, i + 1, 1) == "n") {
				out = out "\\n"
				i++
			} else if (c == "\\" || c == "\"") {
				out = out "\\" c
			} else if (o < 32 || o > 126) {
				out = out sprintf("\\%03o", o)
			} else {
				out = out c
			}
		}
		return out
	}
	KIND == "lang" {
		if ($0 ~ /^[ \t]*(#|$)/)
			next
		EQ = index($0, "=")
		if (EQ == 0) {
			printf "embed.sh: %s:%d: missing \"=\"\n", FILE, NR > "/dev/stderr"
			ERROR = 1
			exit 1
		}
		KEY = substr($0, 1, EQ - 1)
		TEXT = substr($0, EQ + 1)
		sub(/^[ \t]+/, "", KEY)
		sub(/[ \t]+$/, "", KEY)
		sub(/^[ \t]+/, "", TEXT)
		sub(/[ \t]+$/, "", TEXT)
		printf "\t{ \"%s\", \"%s\" },\n", cstr(KEY, 0), cstr(TEXT, 1)
		next
	}
	# Help: "#" lines are comments (the licence header), and the blank
	# lines before the first line of text are dropped with them.
	/^#/ {
		next
	}
	!STARTED && /^[ \t]*$/ {
		next
	}
	{
		STARTED = 1
		printf "\t"
		for (i = 1; i <= length($0); i++)
			printf "\047\\%03o\047, ", ORD[substr($0, i, 1)]
		printf "\047\\n\047,\n"
	}
	END {
		if (ERROR)
			exit 1
		if (KIND == "lang")
			printf "\t{ NULL, NULL }\n};\n"
		else
			printf "\t\047\\0\047\n};\n"
	}
	' "$FILE" || exit 1
done

echo
echo 'const struct catalog_lang catalog_langs[] = {'
for CODE in $LANGS
do
	echo "	{ \"$CODE\", entries_$CODE, help_$CODE },"
done
echo '	{ NULL, NULL, NULL }'
echo '};'
